
import json
import re
from pathlib import Path
from urllib.parse import urlparse

import yaml
from transformers import AutoTokenizer


ROOT = Path(__file__).resolve().parents[2]
CONFIG_PATH = ROOT / "configs" / "corpus.yaml"


def filename_from_url(url: str) -> str:
    """Match the filename generated by 1fetch_docs.py."""
    name = urlparse(url).path.rstrip("/").split("/")[-1] or "index"
    name = re.sub(r"[^a-zA-Z0-9_-]", "_", name)
    return f"{name}.txt"


def main() -> None:
    with CONFIG_PATH.open(encoding="utf-8") as file:
        config = yaml.safe_load(file)

    corpus = config["corpus"]
    settings = config["chunking"]

    corpus_name = corpus["name"]
    source_urls = corpus["source_urls"]
    tokenizer_name = settings["tokenizer"]
    chunk_size = int(settings["chunk_size"])
    overlap = int(settings["chunk_overlap"])

    if chunk_size <= 0 or not 0 <= overlap < chunk_size:
        raise ValueError("Invalid chunk_size or chunk_overlap.")

    tokenizer = AutoTokenizer.from_pretrained(tokenizer_name)

    input_dir = ROOT / "data" / "processed" / corpus_name
    output_path = input_dir / "chunks.jsonl"

    def token_count(text: str) -> int:
        return len(
            tokenizer.encode(text, add_special_tokens=False)
        )

    def split_into_chunks(text: str) -> list[str]:
        """Chunk text while preserving paragraph boundaries where possible."""
        # split extracted text into sections at blank lines (paragraphs)
        sections = [
            section.strip()
            for section in re.split(r"\n\s*\n", text)
            if section.strip()
        ]

        chunks = []
        current_parts = []

        def save_chunk(parts: list[str]) -> None:
            # create a chunk by concatenating current parts with a blank line separator
            content = "\n\n".join(parts).strip() 
            if content:
                chunks.append(content)

        for section in sections:
            # Tokenize the section to check its length
            section_tokens = tokenizer.encode(
                section, add_special_tokens=False
            )

            # Split oversized sections into token windows.
            if len(section_tokens) > chunk_size:
                if current_parts:
                    save_chunk(current_parts)
                    current_parts = []

                step = chunk_size - overlap

                for start in range(0, len(section_tokens), step):
                    window = section_tokens[start:start + chunk_size]
                    if not window:
                        break

                    chunks.append(
                        tokenizer.decode(
                            window,
                            skip_special_tokens=True,
                            clean_up_tokenization_spaces=False,
                        )
                    )

                    if start + chunk_size >= len(section_tokens):
                        break

                continue

            candidate = "\n\n".join(current_parts + [section])

            # if combining next section to current chunk will exceed the chunk size
            if current_parts and token_count(candidate) > chunk_size:
                # list of current sections combined with a blank line
                previous = "\n\n".join(current_parts)
                save_chunk(current_parts)
                # extract overlapping text from previous token and start next chunk with it
                previous_tokens = tokenizer.encode(previous, add_special_tokens=False)
                carried_tokens = previous_tokens[-overlap:] if overlap else []
                carried = tokenizer.decode(
                    carried_tokens,
                    skip_special_tokens=True,
                    clean_up_tokenization_spaces=False,
                ).strip()

                current_parts = [carried] if carried else []

            current_parts.append(section)

        if current_parts:
            save_chunk(current_parts)

        return chunks

    # Read input files, split into chunks, and write to output JSONL file
    records_written = 0
    missing_files = []

    output_path.parent.mkdir(parents=True, exist_ok=True)

    with output_path.open("w", encoding="utf-8") as output_file:
        for source_url in source_urls:
            input_path = input_dir / filename_from_url(source_url)

            if not input_path.is_file():
                missing_files.append(str(input_path))
                print(f"Missing input file: {input_path}")
                continue

            text = input_path.read_text(encoding="utf-8").strip()

            if not text:
                print(f"Skipping empty file: {input_path}")
                continue

            chunks = split_into_chunks(text)

            for content in chunks:
                record = {
                    "chunk_id": f"{corpus_name}_{records_written:05d}",
                    "source": source_url,
                    "tokenizer": tokenizer_name,
                    "token_count": token_count(content),
                    "text": content,
                }

                output_file.write(
                    json.dumps(record, ensure_ascii=False) + "\n"
                )
                records_written += 1

            print(
                f"Processed: {input_path.name} | "
                f"Chunks: {len(chunks)}"
            )

    print(f"\nTokenizer: {tokenizer_name}")
    print(f"Total chunks created: {records_written}")
    print(f"Output: {output_path}")

    if missing_files:
        raise SystemExit(
            f"{len(missing_files)} source file(s) missing. "
            "Resolve these before proceeding."
        )


if __name__ == "__main__":
    main()